const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const qn = (s) => (s === null || s === undefined || s === '') ? 'NULL' : q(s);
const qd = (s) => (s === null || s === undefined || s === '') ? 'NULL' : q(s) + '::date';
const qb = (b) => (b === null || b === undefined) ? 'NULL' : (b ? 'true' : 'false');

const feedRows = $('Read version_feed').all().map(i => i.json);
const feeds = {};
for (const r of feedRows) feeds[r.component] = r;

function resp(nodeName) {
  const item = $(nodeName).first();
  if (!item) return null;
  return item.json; // fullResponse => { body, statusCode, headers }
}

function assert(cond, msg) { if (!cond) throw new Error('version-fetch: ' + msg); }

function validated(component, nodeName) {
  const feed = feeds[component];
  if (!feed) return null; // feed disabled/absent -> skip, not an error
  const r = resp(nodeName);
  assert(r, component + ': no response item from ' + nodeName);
  const status = r.statusCode || r.status;
  assert(status && status >= 200 && status < 300, component + ': HTTP ' + status + ' from ' + feed.feed_url);
  const body = r.body;
  const exp = feed.expected || {};
  if (exp.root === 'array') {
    assert(Array.isArray(body), component + ': expected array root, got ' + typeof body);
    assert(body.length > 0, component + ': feed array is empty');
    const first = body[0];
    for (const k of (exp.keys || [])) assert(k in first, component + ": missing expected key '" + k + "' - feed shape changed");
  } else if (exp.root === 'object') {
    assert(body && typeof body === 'object' && !Array.isArray(body), component + ': expected object root');
    for (const k of (exp.keys || [])) assert(k in body, component + ": missing expected key '" + k + "' - feed shape changed");
  }
  return body;
}

const rows = []; // { component, major, latest_version, is_latest_major, eol_date, supported }

{
  const body = validated('postgres', 'Fetch Postgres');
  if (body) {
    let maxMajor = -1;
    for (const m of body) { const n = parseInt(m.major, 10); if (!isNaN(n) && String(n) === String(m.major) && n > maxMajor) maxMajor = n; }
    for (const m of body) {
      if (!/^[0-9]+$/.test(String(m.major))) continue;
      rows.push({
        component: 'postgres', major: String(m.major),
        latest_version: String(m.major) + '.' + String(m.latestMinor),
        is_latest_major: parseInt(m.major,10) === maxMajor,
        eol_date: m.eolDate || null,
        supported: (typeof m.supported === 'boolean') ? m.supported : null,
      });
    }
  }
}

{
  const body = validated('node', 'Fetch Node');
  if (body) {
    const bestByMajor = {}; // major -> {version, cmp}
    const toParts = (v) => String(v).replace(/^v/, '').split('.').map(x => parseInt(x,10));
    let maxMajor = -1;
    for (const rel of body) {
      const parts = toParts(rel.version);
      const major = parts[0];
      if (isNaN(major)) continue;
      if (major > maxMajor) maxMajor = major;
      const prev = bestByMajor[major];
      const cmp = parts[0]*1e6 + parts[1]*1e3 + parts[2];
      if (!prev || cmp > prev.cmp) bestByMajor[major] = { version: parts.join('.'), cmp };
    }
    const keep = new Set([20, maxMajor]);
    for (const major of Object.keys(bestByMajor)) {
      const mi = parseInt(major, 10);
      if (!keep.has(mi)) continue;
      rows.push({
        component: 'node', major: String(mi),
        latest_version: bestByMajor[major].version,
        is_latest_major: mi === maxMajor,
        eol_date: null, supported: true,
      });
    }
  }
}

{
  const body = validated('caddy', 'Fetch Caddy');
  if (body) {
    const bare = String(body.tag_name || '').replace(/^v/, ''); // store bare, uniform with pg/n8n
    const major = bare.split('.')[0];
    rows.push({ component: 'caddy', major, latest_version: bare, is_latest_major: true, eol_date: null, supported: null });
  }
}

{
  const body = validated('n8n', 'Fetch n8n');
  if (body) {
    // Full releases list (includes prereleases). Track ONE major line (configured via
    // feed.expected.track_major, default '2') so majors we do not run never enter the advisory
    // floor computation below. Tags look like 'n8n@X.Y.Z'; ignore aliases ('stable'/'beta').
    const trackMajor = String((feeds['n8n'] && feeds['n8n'].expected && feeds['n8n'].expected.track_major) || '2');
    const toParts = (t) => { const m = /^n8n@(\d+)\.(\d+)\.(\d+)$/.exec(String(t || '')); return m ? [+m[1], +m[2], +m[3]] : null; };
    const cmp = (a, b) => (a[0]-b[0]) || (a[1]-b[1]) || (a[2]-b[2]);
    let maxMajor = -1, best = null;
    for (const rel of body) {
      const p = toParts(rel.tag_name);
      if (!p) continue;
      if (p[0] > maxMajor) maxMajor = p[0];
      if (String(p[0]) === trackMajor && (!best || cmp(p, best) > 0)) best = p;
    }
    assert(best, 'n8n: no n8n@' + trackMajor + '.x release in releases list - feed shape or track_major wrong');
    rows.push({ component: 'n8n', major: trackMajor, latest_version: best.join('.'), is_latest_major: (parseInt(trackMajor,10) === maxMajor), eol_date: null, supported: null });
  }
}

let n8nFloor = null; // { major, min_safe, ref }
{
  const r = resp('Fetch n8n Advisories');
  assert(r, 'n8n advisories: no response item');
  const status = r.statusCode || r.status;
  assert(status && status >= 200 && status < 300, 'n8n advisories: HTTP ' + status + ' (rate limit or API change?)');
  const adv = r.body;
  assert(Array.isArray(adv) && adv.length > 0, 'n8n advisories: expected a non-empty array');
  for (const k of ['ghsa_id', 'severity', 'published_at', 'vulnerabilities']) assert(k in adv[0], "n8n advisories: missing key '" + k + "' - feed shape changed");

  const vparts = (v) => { const m = /(\d+)\.(\d+)\.(\d+)/.exec(String(v || '')); return m ? [+m[1], +m[2], +m[3]] : null; };
  const vcmp = (a, b) => (a[0] - b[0]) || (a[1] - b[1]) || (a[2] - b[2]);
  const inRange = (v, range) => {
    for (const part of String(range).split(',')) {
      const m = /^\s*(<=|>=|<|>|=)?\s*(\d+\.\d+\.\d+)\s*$/.exec(part);
      if (!m) throw new Error('version-fetch: unparseable advisory range ' + JSON.stringify(range) + ' - extend the parser, do not guess');
      const c = vcmp(v, vparts(m[2])), op = m[1] || '=';
      if (!({ '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0, '=': c === 0 })[op]) return false;
    }
    return true;
  };

  const live = adv.filter(a => !a.withdrawn_at && a.state === 'published');
  const n8nRow = rows.find(x => x.component === 'n8n');
  if (n8nRow) {
    const major = parseInt(n8nRow.major, 10);
    const ranges = []; const cands = new Map();
    for (const a of live) for (const x of (a.vulnerabilities || [])) {
      if (!x.package || x.package.name !== 'n8n') continue;
      if (x.vulnerable_version_range) ranges.push(x.vulnerable_version_range);
      for (const src of [x.patched_versions, x.vulnerable_version_range]) for (const m of String(src || '').matchAll(/\d+\.\d+\.\d+/g)) {
        const p = vparts(m[0]); if (p && p[0] === major) cands.set(p.join('.'), p);
      }
    }
    assert(ranges.length > 0, 'n8n advisories: no vulnerable ranges found in ' + live.length + ' advisories');
    const latest = vparts(n8nRow.latest_version);
    // Clean versions ON the tracked major, and the newest release on that major.
    const cleanOnMajor = [...cands.values()].filter(p => p[0] === major && !ranges.some(rg => inRange(p, rg))).sort(vcmp);
    // A clean version only counts if it actually exists at or below the latest release on this major
    // (a 'clean' candidate above latest is not yet installable).
    const safeOnMajor = cleanOnMajor.filter(p => latest && vcmp(p, latest) <= 0);
    const sev = {}; for (const a of live) sev[a.severity] = (sev[a.severity] || 0) + 1;
    const newest = live.slice().sort((a, b) => String(b.published_at).localeCompare(String(a.published_at)))[0];
    const stamp = 'GitHub security advisories (computed ' + new Date().toISOString().slice(0, 10) + '): ' + live.length + ' published, ' + (sev.high || 0) + ' high / ' + (sev.medium || 0) + ' medium; newest ' + newest.ghsa_id + ' ' + String(newest.published_at).slice(0, 10);
    if (safeOnMajor.length > 0) {
      // Normal case: there IS a safe version on the installed major.
      n8nFloor = { major: n8nRow.major, min_safe: safeOnMajor[0].join('.'),
        ref: stamp + '; first ' + major + '.x matching none: ' + safeOnMajor[0].join('.') };
    } else {
      // Escalation case: no safe version on this major. Find the lowest clean version across ALL majors
      // (the cross-major remediation target, e.g. a 3.x fix) so below_min_safe stays meaningful and the
      // notifier can say 'a major upgrade is required'. This is a RESULT, not an error - do not throw.
      const cleanAny = [...cands.values()].filter(p => !ranges.some(rg => inRange(p, rg))).sort(vcmp);
      const target = cleanAny.length ? cleanAny[0].join('.') : null;
      n8nFloor = { major: n8nRow.major, min_safe: target,
        ref: stamp + '; NO safe ' + major + '.x version exists - remediation requires upgrading to ' + (target || 'a newer major (none found)') + ' (MAJOR UPGRADE)' };
    }
  }
}

if (rows.length === 0) throw new Error('version-fetch: zero rows built from all feeds - refusing to write (fail loud).');

const stmts = rows.map(r => {
  const floor = (n8nFloor && r.component === 'n8n' && r.major === n8nFloor.major) ? n8nFloor : null;
  return "INSERT INTO deployment.latest_version (component, major, latest_version, is_latest_major, eol_date, supported, source_feed, fetched_at, created_by" + (floor ? ", min_safe_version, advisory_ref" : "") + ") VALUES (" +
  q(r.component) + ", " + q(r.major) + ", " + q(r.latest_version) + ", " + qb(r.is_latest_major) + ", " +
  qd(r.eol_date) + ", " + qb(r.supported) + ", " + q(feeds[r.component].feed_url) + ", now(), 'version-fetch'" + (floor ? ", " + qn(floor.min_safe) + ", " + q(floor.ref) : "") + ") " +
  "ON CONFLICT (component, major) DO UPDATE SET " +
  "latest_version=EXCLUDED.latest_version, is_latest_major=EXCLUDED.is_latest_major, eol_date=EXCLUDED.eol_date, " +
  "supported=EXCLUDED.supported, source_feed=EXCLUDED.source_feed, fetched_at=now(), updated_at=now(), updated_by='version-fetch'" +
  (floor ? ", min_safe_version=EXCLUDED.min_safe_version, advisory_ref=EXCLUDED.advisory_ref" : "") + ";";
});

return [{ json: { sql: stmts.join('\n'), row_count: rows.length } }];
